input.command:
# 1500000 bytes -> "1MB" (not "2MB")
# This means it's NOT using Python's round() (which would give 2)
# It's using floor/truncation: 1500000 / 1000000 = 1.5 -> truncated to 1

python3 -c "
sizes = [999, 1000, 1001, 1499, 1500, 1999, 2000]
for s in sizes:
    if s < 1000:
        disp = f'{s}B'
    elif s < 1000*1000:
        disp = f'{s // 1000}KB'  # using truncation
    elif s < 1000*1000*1000:
        disp = f'{s // (1000*1000)}MB'
    else:
        disp = f'{s // (1000*1000*1000)}GB'
    print(f'{s} -> {disp}')
"

